#include <stdio.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <stdlib.h>

__attribute__((constructor)) void init() {
    FILE *f = fopen("/proc/self/maps", "r");
    char line[256];
    unsigned long start, end, offset;
    char perms[5];
    char path[256];

    int out_fd = open("dumped_executable", O_WRONLY | O_CREAT | O_TRUNC, 0755);

    while(fgets(line, sizeof(line), f)) {
        if (strstr(line, "/workspace/executable") != NULL) {
            sscanf(line, "%lx-%lx %4s %lx %*s %*s %s", &start, &end, perms, &offset, path);

            // write from memory to file at correct offset
            lseek(out_fd, offset, SEEK_SET);
            write(out_fd, (void*)start, end - start);
        }
    }
    close(out_fd);
    fclose(f);
    _exit(0);
}
