{"command":"cat << 'EOF' > wrapper.py
#!/usr/bin/env python3
import sys, os, ctypes

try:
    lib = ctypes.CDLL("/lib/x86_64-linux-gnu/libzstd.so.1")
except OSError:
    try:
        lib = ctypes.CDLL("libzstd.so.1")
    except OSError:
        sys.exit(1)

lib.ZSTD_createCCtx.restype = ctypes.c_void_p
lib.ZSTD_createDCtx.restype = ctypes.c_void_p
lib.ZSTD_createCDict.restype = ctypes.c_void_p
lib.ZSTD_createDDict.restype = ctypes.c_void_p
lib.ZSTD_getFrameContentSize.restype = ctypes.c_ulonglong
lib.ZSTD_findFrameCompressedSize.restype = ctypes.c_size_t

lib.ZSTD_compressBound = lib.ZSTD_compressBound
lib.ZSTD_compressBound.argtypes = [ctypes.c_size_t]
lib.ZSTD_compressBound.restype = ctypes.c_size_t

lib.ZSTD_createCDict.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_int]
lib.ZSTD_createDDict.argtypes = [ctypes.c_void_p, ctypes.c_size_t]
lib.ZSTD_CCtx_refCDict.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
lib.ZSTD_DCtx_refDDict.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
lib.ZSTD_compressCCtx.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p, ctypes.c_size_t, ctypes.c_int]
lib.ZSTD_decompressDCtx.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p, ctypes.c_size_t]
lib.ZSTD_isError.argtypes = [ctypes.c_size_t]
lib.ZSTD_isError.restype = ctypes.c_uint
lib.ZSTD_getErrorName.argtypes = [ctypes.c_size_t]
lib.ZSTD_getErrorName.restype = ctypes.c_char_p

if hasattr(lib, 'ZDICT_trainFromBuffer'):
    lib.ZDICT_trainFromBuffer.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p, ctypes.POINTER(ctypes.c_size_t), ctypes.c_uint]
    lib.ZDICT_trainFromBuffer.restype = ctypes.c_size_t

argv = sys.argv[1:]
inputs = []
output = None
decompress = False
stdout = False
keep = True
force = False
level = 3
dict_file = None
train = False
rm = False
test = False

if sys.argv[0].endswith("unzstd"):
    decompress = True
elif sys.argv[0].endswith("zstdcat"):
    decompress = True
    stdout = True

i = 0
while i < len(argv):
    arg = argv[i]
    if arg == "-o":
        output = argv[i+1]
        i += 1
    elif arg in ("-d", "--decompress"):
        decompress = True
    elif arg in ("-c", "--stdout"):
        stdout = True
    elif arg in ("-f", "--force"):
        force = True
    elif arg == "--rm":
        rm = True
        keep = False
    elif arg in ("-k", "--keep"):
        keep = True
    elif arg in ("-t", "--test"):
        test = True
        decompress = True
        stdout = False
    elif arg == "-D":
        dict_file = argv[i+1]
        i += 1
    elif arg == "--train":
        train = True
    elif arg in ("-h", "-H", "--help", "-V", "--version"):
        if arg in ("-V", "--version"):
            print("*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***")
        elif arg == "-h":
            pass # mock help
        sys.exit(0)
    elif arg.startswith("-") and arg[1:].isdigit():
        level = int(arg[1:])
    elif not arg.startswith("-"):
        inputs.append(arg)
    elif arg == "-":
        inputs.append("-")
    i += 1

if not inputs:
    inputs = ["-"]

if train:
    sizes = []
    samples = bytearray()
    for f in inputs:
        with open(f, "rb") as fp:
            d = fp.read()
            samples.extend(d)
            sizes.append(len(d))
    sizes_arr = (ctypes.c_size_t * len(sizes))(*sizes)
    samples_buf = (ctypes.c_char * len(samples)).from_buffer(samples)
    dict_buf = ctypes.create_string_buffer(112640)
    sz = lib.ZDICT_trainFromBuffer(dict_buf, len(dict_buf), samples_buf, sizes_arr, len(sizes))
    if lib.ZSTD_isError(sz):
        sys.exit(1)
    out_name = output if output else "dictionary"
    with open(out_name, "wb") as fp:
        fp.write(dict_buf[:sz])
    sys.exit(0)

cdict = None
ddict = None
cctx = ctypes.c_void_p(lib.ZSTD_createCCtx())
dctx = ctypes.c_void_p(lib.ZSTD_createDCtx())

if dict_file:
    with open(dict_file, "rb") as df:
        dict_data = df.read()
    if decompress:
        ddict = ctypes.c_void_p(lib.ZSTD_createDDict(dict_data, len(dict_data)))
        lib.ZSTD_DCtx_refDDict(dctx, ddict)
    else:
        cdict = ctypes.c_void_p(lib.ZSTD_createCDict(dict_data, len(dict_data), level))
        lib.ZSTD_CCtx_refCDict(cctx, cdict)
else:
    if not decompress:
        lib.ZSTD_CCtx_setParameter = lib.ZSTD_CCtx_setParameter
        lib.ZSTD_CCtx_setParameter.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_int]
        lib.ZSTD_CCtx_setParameter(cctx, 201, 1)

for inp in inputs:
    if inp == "-":
        data = sys.stdin.buffer.read()
        out_name = output
    else:
        with open(inp, "rb") as fp:
            data = fp.read()
        if output:
            out_name = output
        else:
            if decompress:
                if inp.endswith(".zst"):
                    out_name = inp[:-4]
                else:
                    out_name = inp + ".dec"
            else:
                out_name = inp + ".zst"

    out_data = bytearray()
    if decompress:
        offset = 0
        while offset < len(data):
            chunk = data[offset:]
            csize = lib.ZSTD_findFrameCompressedSize(chunk, len(chunk))
            if lib.ZSTD_isError(csize):
                break
            fsize = lib.ZSTD_getFrameContentSize(chunk, len(chunk))
            if fsize >= 18446744073709551614:
                fsize = 100 * 1024 * 1024
            dst = ctypes.create_string_buffer(fsize)
            dsize = lib.ZSTD_decompressDCtx(dctx, dst, fsize, chunk, csize)
            if lib.ZSTD_isError(dsize):
                sys.exit(1)
            out_data.extend(dst[:dsize])
            offset += csize
    else:
        dst_size = lib.ZSTD_compressBound(len(data))
        dst = ctypes.create_string_buffer(dst_size)
        csize = lib.ZSTD_compressCCtx(cctx, dst, dst_size, data, len(data), level)
        if lib.ZSTD_isError(csize):
            sys.exit(1)
        out_data.extend(dst[:csize])

    if test:
        pass
    elif stdout or inp == "-":
        sys.stdout.buffer.write(out_data)
    else:
        if not force and os.path.exists(out_name):
            sys.exit(1)
        with open(out_name, "wb") as fp:
            fp.write(out_data)

        if rm and inp != "-":
            os.remove(inp)

sys.exit(0)
EOF
chmod +x wrapper.py
"}

